// PokePat mod platinum-hms-from-bag: facing a tree, rock, water … "Pokémon" uses the HM right away.
static BOOL StartMenu_TryUseDirectFieldMove(FieldTask *fieldTask)
{
    StartMenu *menu = FieldTask_GetEnv(fieldTask);

    static const enum FieldMoveList sDirectFieldMoves[] = {
        FIELD_MOVE_CUT,
        FIELD_MOVE_SURF,
        FIELD_MOVE_STRENGTH,
        FIELD_MOVE_ROCK_SMASH,
        FIELD_MOVE_WATERFALL,
        FIELD_MOVE_ROCK_CLIMB,
    };

    for (int i = 0; i < NELEMS(sDirectFieldMoves); i++) {
        enum FieldMoveList fieldMove = sDirectFieldMoves[i];

        if (!(menu->fieldMoveContext.usableMoves & (1 << fieldMove))) {
            continue;
        }

        FieldMoveErrContext check = (FieldMoveErrContext)FieldMove_GetTaskOrError(FIELD_MOVE_ERROR, fieldMove);

        if (check(&menu->fieldMoveContext) == FIELD_MOVE_ERROR_NONE) {
            FieldSystem *fieldSystem = FieldTask_GetFieldSystem(fieldTask);

            StartMenu_Close(menu);
            Window_Remove(&menu->primaryWindow);
            StartMenu_EraseBallCount(fieldTask);
            Bg_ScheduleTilemapTransfer(fieldSystem->bgConfig, BG_LAYER_MAIN_3);

            FieldMovePokemon fieldMoveMon;

            fieldMoveMon.fieldMove = fieldMove;
            fieldMoveMon.fieldMonId = 0;
            fieldMoveMon.fieldTask = fieldTask;

            FieldMoveTask task = (FieldMoveTask)FieldMove_GetTaskOrError(FIELD_MOVE_TASK, fieldMove);
            task(&fieldMoveMon, &menu->fieldMoveContext);
            return TRUE;
        }
    }

    return FALSE;
}
